SELECT id, user_id, module, action, resource_type, resource_id, request_id,
       ip_address, before_json, after_json, create_time
FROM sys_audit_log

    AND module = #{module}
    AND action = #{action}
    AND create_time >= #{from}
    AND create_time <= #{to}

ORDER BY id DESC
LIMIT #{offset}, #{size}

SELECT COUNT(*)
FROM sys_audit_log

    AND module = #{module}
    AND action = #{action}
    AND create_time >= #{from}
    AND create_time <= #{to}
